{"command":"python3 - <<'PY'
import hashlib, json, os
from pathlib import Path

SRC = Path("<MAINTAINER_LOCAL_PATH>")
manifest = json.load(open(SRC/"manifest.json", encoding="utf-8"))
mfile = {f["path"]: f for f in manifest["files"]}

def sha(p):
    h = hashlib.sha256()
    with open(p, "rb") as f:
        for b in iter(lambda: f.read(65536), b""): h.update(b)
    return h.hexdigest()

# list all files under outputs/
local = sorted(p for p in Path("outputs").rglob("*") if p.is_file())
print("local outputs/ file count:", len(local))
all_ok = True
for p in local:
    rel = "outputs/" + str(p.relative_to("outputs"))
    if rel not in mfile:
        print("  UNTRACKED:", rel); all_ok &= False; continue
    sz = os.path.getsize(p)
    got = sha(p)
    want = mfile[rel]["sha256"]
    ok = (got == want) and (sz == mfile[rel]["size_bytes"])
    if not ok: all_ok &= False; print("  MISMATCH", rel, "got", got, "want", want, "size", sz, mfile[rel]["size_bytes"])
    else: print("  OK", rel, sz, got[:16]+"...")
print("ALL_11_SYSTEMS_OK=", all_ok)
# cache scan
caches = [str(p) for p in Path("outputs").rglob("*") if p.name=="__pycache__" or p.suffix in (".pyc",".pyo")]
print("cache/pyc entries:", caches)
PY","description":"Final integrity sweep of outputs systems files"}

